    "description": "新华社土耳其恰纳卡莱8月12日电（记者王科文）第63届国际特洛伊节10日至12日在土耳其恰纳卡莱举行。活动以古希腊诗人荷马笔下的特洛伊古城为文化依托，举办音乐会、展览、座谈等多项文化活动及体育赛事，吸引了众多来宾。 特洛伊古城遗址位于恰纳卡莱省境内，因荷马史诗《伊利亚特》记载的特洛伊战争而闻名于世。2004年电影《特洛伊》中使用的巨型木马道具，如今矗立在恰纳卡莱市的海滨，成为该城的标志性象征。 漫步恰纳卡莱街头，特洛伊节的氛围随处可见。…",
    "content": "新华社土耳其恰纳卡莱8月12日电（记者王科文）第63届国际特洛伊节10日至12日在土耳其恰纳卡莱举行。活动以古希腊诗人荷马笔下的特洛伊古城为文化依托，举办音乐会、展览、座谈等多项文化活动及体育赛事，吸引了众多来宾。 特洛伊古城遗址位于恰纳卡莱省境内，因荷马史诗《伊利亚特》记载的特洛伊战争而闻名于世。2004年电影《特洛伊》中使用的巨型木马道具，如今矗立在恰纳卡莱市的海滨，成为该城的标志性象征。 漫步恰纳卡莱街头，特洛伊节的氛围随处可见。城市主干道、广场、文化场馆和市政厅建筑外都能看到醒目的节日宣传物料，巨幅宣传条幅…"
