    "description": "新华社华盛顿8月11日电 据美国有线电视新闻网11日报道，美国东部地区当天遭遇强烈风暴，导致至少2人死亡，超过80万户用户断电。 地方官员说，在印第安纳州，一棵大树被狂风刮倒后砸中一处民宅，造成一名4岁儿童死亡；在俄亥俄州，风暴引发的洪水导致一人死亡。 另据全美停电信息网数据显示，截至美国东部时间11日午夜，伊利诺伊州、印第安纳州、俄亥俄州和肯塔基州共有超过80万户用户断电。",
