    "content": "中新网吉林8月12日电 (记者 石洪宇)吉林市政府新闻办公室12日举行新闻发布会，介绍《吉林市国民经济和社会发展第十五个五年规划纲要》(下称《规划纲要》)相关情况。根据《规划纲要》，吉林市“十五五”期间将打造世界级冰雪产业基地和世界级碳纤维产业基地，推动冰雪旅游总花费达到900亿元。"
