    "description": "兰考地处豫东黄河故道，曾饱受风沙、盐碱、内涝“三害”之苦。上世纪60年代，当地广植泡桐以防风固沙。后来人们发现，泡桐木质疏松、不易变形、导音性强，恰好适合制作民族乐器音板。昔日的治沙树，由此成为兰考民族乐器产业的重要基础。",
