    "author": "Monet23",
    "description": "最近业余时间做了一个小工具，叫 DevResume ，想发出来请 V 友帮忙挑挑问题。 最开始的版本也很直接：把简历和 JD 一起交给模型，让它生成一份“更专业”的表述。但实际用下来很快遇到两个问题：一是慢，二是模型会一本正经地补充原文里没有的事实。句子看着漂亮，面试时却可能根本解释不清。 后来陆续重做了几轮，现在主要有这些能力： 上传 PDF 简历，或者从 GitHub / GitLab / Gitee 导入项目材料； 选中工作经历或…",
