    "pub_date": "2026-08-12 14:10:22",
    "author": "",
    "description": "记者今天(12日)从中国期货业协会了解到，以单边计算，今年1-7月全国期货市场累计成交量为61.07亿手，累计成交额为568.98万亿元，同比分别增长18.93%和38.43%。其中7月全国期货市场成交量为10.02亿手，成交额为86.28万亿元，同比分别下降5.31%和增长20.99%。",
    "content": "记者今天(12日)从中国期货业协会了解到，以单边计算，今年1-7月全国期货市场累计成交量为61.07亿手，累计成交额为568.98万亿元，同比分别增长18.93%和38.43%。其中7月全国期货市场成交量为10.02亿手，成交额为86.28万亿元，同比分别下降5.31%和增长20.99%。"
