    "title": "印度散户股票衍生品交易一年亏损96亿美元，监管遏制措施成效有限",
    "link": "https://36kr.com/newsflashes/3936121138510983?f=rss",
    "pub_date": "2026-08-12 13:49:28",
    "author": "",
    "description": "在截至3月的这一年中，印度散户在股票期货和期权交易中损失了9168.5亿卢比（96亿美元），说明监管部门为遏制个人投资者巨额亏损采取的措施收效有限。印度官员Pankaj Chaudhary在书面回复中表示，这段时期的亏损较上年的1.1万亿卢比略有减少，同期参与交易的投资者人数从980万人降至不足800万人。（新浪财经）",
    "content": "在截至3月的这一年中，印度散户在股票期货和期权交易中损失了9168.5亿卢比（96亿美元），说明监管部门为遏制个人投资者巨额亏损采取的措施收效有限。印度官员Pankaj Chaudhary在书面回复中表示，这段时期的亏损较上年的1.1万亿卢比略有减少，同期参与交易的投资者人数从980万人降至不足800万人。（新浪财经）"
