    "description": "日夜奔腾的长江，横贯湖北1061公里。波涌浪打，妩媚多姿。作为长江大保护的“立规之地”和主战场，湖北努力探索生态优先、绿色发展新路，实施长江大保护“双十工程”“双十行动”和“十年禁渔”战略。不忘谆谆教诲，十年砥砺前行，以敢为人先的勇气、志在必得的决心和坚持不懈的毅力，书写荆楚大地最精彩、最壮观的“长江答卷”。十年磨砺，山清水秀。一幅青山绿水、鱼翔浅底、江豚逐浪的美丽画卷深情铺展。",
