    "description": "韩亚航空8月12日召开临时股东大会，表决通过与大韩航空合并案。两家公司将于今年12月17日正式合并为“大韩航空”。大韩航空2020年11月正式宣布收购韩亚航空后，经过国内外竞争部门的企业合并审议，推进合并所需流程。韩亚航空表示，股东大会批准企业合并协议后，公司将据此切实推进各项跟进措施。大韩航空8月12日也将召开董事会，审议表决合并协议。（财联社）",
    "content": "韩亚航空8月12日召开临时股东大会，表决通过与大韩航空合并案。两家公司将于今年12月17日正式合并为“大韩航空”。大韩航空2020年11月正式宣布收购韩亚航空后，经过国内外竞争部门的企业合并审议，推进合并所需流程。韩亚航空表示，股东大会批准企业合并协议后，公司将据此切实推进各项跟进措施。大韩航空8月12日也将召开董事会，审议表决合并协议。（财联社）"
