    "pub_date": "2026-08-12 13:23:31",
    "author": "",
    "description": "中新网南宁8月12日电(林浩 韦佳秀)广西壮族自治区政府办公厅近日印发《广西海洋经济发展“十五五”规划》(以下简称《规划》)，提出以打造“产业海洋、科技海洋、开放海洋、生态海洋”为主攻方向，加快构建现代海洋产业体系，培育海洋领域新质生产力。到2030年，广西海洋生产总值占地区生产总值比重力争达10%左右。",
    "content": "中新网南宁8月12日电(林浩 韦佳秀)广西壮族自治区政府办公厅近日印发《广西海洋经济发展“十五五”规划》(以下简称《规划》)，提出以打造“产业海洋、科技海洋、开放海洋、生态海洋”为主攻方向，加快构建现代海洋产业体系，培育海洋领域新质生产力。到2030年，广西海洋生产总值占地区生产总值比重力争达10%左右。"
