    "title": "韦布望远镜在银河系中心黑洞附近发现水和尘埃",
    "link": "http://www.news.cn/20260812/20e8894e69004487896412c5dc5d38c8/c.html",
    "pub_date": "2026-08-12 13:03:36",
    "author": "罗毓",
    "description": "新华社巴黎8月11日电（记者罗毓）欧洲航天局11日在官网发布公报说，一个国际天文学家团队通过分析美国詹姆斯·韦布空间望远镜2025年的观测数据发现，在银河系中心超大质量黑洞附近一颗处于演化晚期的恒星周围存在水和富氧尘埃。这一发现表明，即使处于强烈辐射环境中，演化晚期的恒星仍可持续向周围空间释放形成恒星和行星所需的物质。 研究团队此次重点观测的是恒星IRS 3，它距离银河系中心超大质量黑洞人马座A*仅约0.55光年，是银河系中心最明亮的中…",
    "content": "新华社巴黎8月11日电（记者罗毓）欧洲航天局11日在官网发布公报说，一个国际天文学家团队通过分析美国詹姆斯·韦布空间望远镜2025年的观测数据发现，在银河系中心超大质量黑洞附近一颗处于演化晚期的恒星周围存在水和富氧尘埃。这一发现表明，即使处于强烈辐射环境中，演化晚期的恒星仍可持续向周围空间释放形成恒星和行星所需的物质。 研究团队此次重点观测的是恒星IRS 3，它距离银河系中心超大质量黑洞人马座A*仅约0.55光年，是银河系中心最明亮的中红外辐射源之一。IRS 3已进入生命接近末期的一个演化阶段，在这个被称为“渐近巨…"
