    "description": "清晨六点，苏州河上还飘着薄雾。王彦升穿过宜昌消防救援站的操场，在那口老铜钟前停了一下。这是他每天的习惯——抬头看一眼钟，再看一眼那座42米高的瞭望塔。塔身斑驳，钟面泛绿，但钟声敲了一百年，从来没有哑过。 以前敲钟是为了报警。那时没有电话，发现火情就撞钟，钟声一响，队员从四面八方往站里跑。现在，钟声的意义变了。王彦升说，它代表平安，代表忠诚，还有一个意思——“始终”。一百年了，队伍换了一茬又一茬人，钟声始终在响。 他是这里的指导员，90后…",
