    "content": "三星去年引入了首台High-NA EUV光刻机，安装在华城园区，成为了英特尔（2023年末）和台积电（2024年第三季度）之后，第三家安装High-NA EUV光刻机的半导体制造商。今年三星又新装了第二台High-NA EUV光刻机，现阶段更多地、停留在技术研发和试用阶段，还没有用于大规模生产的打算。按照原计划，三星打算在下一代1.4nm制程节点和DRAM芯片生产中引入High-NA EUV技术。 据TrendForce 报道 ，目前三星基于2nm的SF2工艺在生产方面已逐步走上正轨，计划2029年开始量产初代1.…"
