    "content": "近日，“弟弟举报哥哥冒名顶替上大学”一事引发关注，8月11日，弟弟唐向西(化名)在北京向中新网表示，自己此前的名字是唐向东(化名)，他与哥哥2001年高考时，自己没去就读湘潭大学而选择复读，成绩不如自己的哥哥以唐向东的名字入读湘潭大学。弟弟本人则改名“唐向西”，于第二年考入中国人民大学。"
