    "author": "王安浩维,胡超,唐榕苓",
    "description": "8月12日是世界大象日。亚洲象不仅是雨林中的“巨型居民”，也是生态系统的“工程师”。它们通过取食和活动传播植物种子、影响森林结构，并为其他生物创造生存空间。一头大象的日常行为，背后连接着整个雨林的生命循环。 记者：胡超、唐榕苓、王安浩维 部分画面来源：西双版纳州亚洲象保护管理中心 新华社音视频部制作",
