    "content": "新华社北京8月12日电（记者王聿昊、张骁）记者从中国国航获悉，由C919执飞的国航CA723航班将于12日15时许从北京首都国际机场起飞，前往蒙古国首都乌兰巴托，这是C919首次执飞国际商业航班。 C919大型客机是我国首次按照国际通行适航标准自行研制、具有自主知识产权的喷气式干线客机，于2023年5月28日完成首次商业飞行。 中国商飞数据显示，截至8月10日，由国航、东航、南航运营的C919客机累计开通57条航线，通航25座城市，安全运送旅客超750万人次。"
