    "pub_date": "2026-08-12 11:10:20",
    "author": "王曦",
    "description": "新华社成都8月12日电（记者王曦）八月，北半球多地热浪翻涌，四川九寨沟却以20℃左右的宜人气温，向世界敞开一扇清凉之门。随着240小时过境免签政策全面落地、入境支付便利化持续提升，越来越多的外国游客选择扎进这片高原凉谷，在碧水叠瀑间开启一场避暑之旅。 8月5日，游客在四川九寨沟景区五花海游览。新华社记者 王曦 摄 清晨七点半，九寨沟沟口已是人流如织，当天游客预订门票超35000张，十余个进沟通道排起长龙。来自法国的费朗迪排队刷护照进入景…",
    "content": "新华社成都8月12日电（记者王曦）八月，北半球多地热浪翻涌，四川九寨沟却以20℃左右的宜人气温，向世界敞开一扇清凉之门。随着240小时过境免签政策全面落地、入境支付便利化持续提升，越来越多的外国游客选择扎进这片高原凉谷，在碧水叠瀑间开启一场避暑之旅。 8月5日，游客在四川九寨沟景区五花海游览。新华社记者 王曦 摄 清晨七点半，九寨沟沟口已是人流如织，当天游客预订门票超35000张，十余个进沟通道排起长龙。来自法国的费朗迪排队刷护照进入景区，眼前的景象让他颇感意外——没有拥挤推搡，没有嘈杂喧哗，游客们在工作人员的引导…"
